public class Counter implements Runnable {
    private static int count = 0;      // shared by every thread

    public void run() {
        for (int i = 0; i < 100000; i++) {
            count++;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(new Counter());
        Thread t2 = new Thread(new Counter());

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Expected: 200000");
        System.out.println("Actual:   " + count);
    }
}

public class Counter implements Runnable {
    private static int count = 0;

    private static synchronized void increment() {    // only one thread at a time
        count++;
    }

    public void run() {
        for (int i = 0; i < 100000; i++) {
            increment();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(new Counter());
        Thread t2 = new Thread(new Counter());

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Actual: " + count);       // 200000, every time
    }
}

import java.util.concurrent.atomic.AtomicInteger;

AtomicInteger count = new AtomicInteger(0);

Runnable task = () -> {
    for (int i = 0; i < 100000; i++) {
        count.incrementAndGet();   // one atomic step
    }
};

// two threads running task, then join() on both: count.get() is 200000, every time
